b=Bank(3)

# S3.1 shared: periodic position, trends, oxides and chemical group behaviour.
positions=[(r'[Ne]3s^{2}3p^{3}',3,15,'p'),(r'[Ar]4s^{2}',4,2,'s'),(r'[He]2s^{2}2p^{5}',2,17,'p'),(r'[Ar]3d^{10}4s^{2}4p^{2}',4,14,'p')]
for v,(conf,period,group,block) in enumerate(positions,1):
    answer=f'Period {period}, group {group}, {block} block'
    b.add('S31-periodic-position','S3.1',v,'Locating an element',f'A neutral ground-state atom has electron configuration {m(conf)}. Which periodic-table position is correct?',options=[answer,f'Period {period+1}, group {group}, {block} block',f'Period {period}, group {group-1}, {block} block',f'Period {period}, group {group}, '+('d' if block=='p' else 'p')+' block'],reason=f'The highest occupied principal level is {period}. The valence configuration places the element in group {group}; its differentiating electron occupies the {block} block.')

radii=[('Na','Mg','Both atoms have valence electrons in the third shell; magnesium has one more proton.','Na','Across the period, nuclear charge increases while added electrons occupy the same principal shell, so the effective nuclear attraction increases and atomic radius decreases.'),('Li','Na','Lithium has occupied shells up to n = 2; sodium has occupied shells up to n = 3.','Na','An extra occupied shell and greater shielding make sodium larger despite its greater nuclear charge.'),('O²⁻','F⁻','Both ions contain ten electrons; their nuclear charges are +8 and +9, respectively.','O²⁻','In an isoelectronic series, the lower nuclear charge attracts the same electron cloud less strongly, giving the larger radius.'),('Na⁺','Mg²⁺','Both ions contain ten electrons; their nuclear charges are +11 and +12, respectively.','Na⁺','The ion with the greater nuclear charge attracts the same number of electrons more strongly and is smaller.')]
for v,(x,y,info,larger,why) in enumerate(radii,1):
    b.add('S31-radii','S3.1',v,'Explaining a radius comparison',f'Compare the radii of {x} and {y}. {info}',parts=[P('Identify the larger species and explain the trend.',A(larger+' is larger.'),Rn(why)),P('Distinguish nuclear charge from ionic charge.',A('Nuclear charge depends on proton number; ionic charge is the difference between proton and electron numbers.'))])

trenditems=[('Which atom is expected to be more electronegative: sulfur or chlorine?','Chlorine, because attraction for a shared electron pair generally increases across a period.',['Sulfur, because fewer protons always increase electronegativity.','They must be equal because they are in the same period.','Neither can attract bonding electrons because both are non-metals.'],'Across period 3 the nuclear charge increases with similar shielding, so chlorine attracts bonding electrons more strongly.'),('Which atom is expected to be more electronegative: fluorine or bromine?','Fluorine, because its bonding electrons are closer to the nucleus and less shielded.',['Bromine, solely because its nucleus has more protons.','They must be equal because both form −1 ions.','Bromine, because adding occupied shells always strengthens attraction for bonding electrons.'],'Down group 17, greater radius and shielding reduce the attraction for a shared electron pair.'),('What is meant by electronegativity?','The ability of an atom in a covalent bond to attract the shared electrons.',['The energy needed to remove a mole of neutrons.','The number of neutrons in the most common isotope.','The charge on a free isolated nucleus.'],'Electronegativity describes attraction for a bonding electron pair, not an isolated atom’s charge or neutron count.'),('Across period 3 from sodium to chlorine, what is the broad trend in metallic character?','It decreases as atoms become less likely to lose electrons.',['It increases because the atoms contain more electrons.','It remains constant because the period number is fixed.','It changes only when an isotope is replaced.'],'Increasing effective nuclear attraction across the period reduces the tendency to lose valence electrons, so metallic character decreases.')]
for v,(stem,ans,wrong,why) in enumerate(trenditems,1):
    b.add('S31-periodic-trends','S3.1',v,'Interpreting a periodic trend',stem,options=[ans]+wrong,reason=why)

oxides=[('Na2O','basic','The oxide contains oxide ions that accept protons.',c('Na2O')+' + 2'+c('HCl')+' → 2'+c('NaCl')+' + '+c('H2O'),'sodium oxide reacts with dilute hydrochloric acid'),('MgO','basic','Oxide ions react with protons to form water.',c('MgO')+' + 2'+c('HCl')+' → '+c('MgCl2')+' + '+c('H2O'),'magnesium oxide reacts with dilute hydrochloric acid'),('Al2O3','amphoteric','It reacts with both acids and bases.',c('Al2O3')+' + 6'+c('HCl')+' → 2'+c('AlCl3')+' + 3'+c('H2O'),'aluminium oxide reacts with hydrochloric acid'),('SiO2','acidic','It reacts with a strong base to form a silicate.',c('SiO2')+' + 2'+c('NaOH')+' → '+c('Na2SiO3')+' + '+c('H2O'),'silicon dioxide reacts with hot concentrated sodium hydroxide')]
for v,(formula,nature,why,equation,event) in enumerate(oxides,1):
    b.add('S31-oxide-character','S3.1',v,'Acid-base character of a period 3 oxide',f'Consider {c(formula)}. In a demonstration, {event}.',parts=[P('Classify the oxide as basic, amphoteric or acidic and justify the classification.',A(nature.capitalize()+'.'),Rn(why)),P('Write a balanced equation for the stated reaction.',A(equation+'.')),P('State the general change in oxide acid-base character from the left to the right of period 3.',A('The oxides broadly change from basic through amphoteric to acidic.'))])

groupchem=[('chlorine is bubbled through aqueous potassium bromide','The solution becomes orange as bromine forms.',c('Cl2')+' + 2'+c('Br','-')+' → 2'+c('Cl','-')+' + '+c('Br2'),'Chlorine is the stronger oxidizing agent and accepts electrons from bromide ions.'),('bromine is added to aqueous potassium iodide','A brown iodine-containing solution forms.',c('Br2')+' + 2'+c('I','-')+' → 2'+c('Br','-')+' + '+c('I2'),'Bromine is the stronger oxidizing agent and accepts electrons from iodide ions.'),('sodium is added to excess water','Hydrogen gas and an alkaline solution are produced.','2'+c('Na')+' + 2'+c('H2O')+' → 2'+c('NaOH')+' + '+c('H2'),'Sodium loses its outer electron; the hydroxide formed makes the solution alkaline.'),('potassium is added to excess water','Hydrogen gas and an alkaline solution are produced.','2'+c('K')+' + 2'+c('H2O')+' → 2'+c('KOH')+' + '+c('H2'),'Potassium loses its outer electron; the hydroxide formed makes the solution alkaline.')]
for v,(event,obs,eq,why) in enumerate(groupchem,1):
    b.add('S31-group-reactivity','S3.1',v,'Predicting group behaviour',f'In a controlled demonstration, {event}. {obs}',parts=[P('Write a balanced equation for the reaction. Use an ionic equation for a halogen displacement.',A(eq+'.')),P('Explain the reaction in terms of the characteristic behaviour of the group.',Rn(why)),P('State and explain the relevant reactivity trend down the group.',A('Halogen oxidizing strength decreases down group 17.' if v<3 else 'The reactivity of group 1 metals with water generally increases down the group.'),Rn('Greater shielding and radius reduce attraction for an incoming electron.' if v<3 else 'Greater shielding and radius make the outer electron easier to remove.'))])

# AHL: first-ionization anomalies, transition ions, coordination and d-level colour.
exceptions=[('Be','B',900,800,'The electron removed from B occupies a higher-energy 2p orbital, while that from Be occupies 2s.'),('Mg','Al',740,580,'The electron removed from Al occupies a higher-energy 3p orbital, while that from Mg occupies 3s.'),('N','O',1400,1310,'O has a paired 2p electron; repulsion within that orbital makes its removal easier than removal from the singly occupied 2p orbitals of N.'),('P','S',1010,1000,'S has a paired 3p electron; repulsion within that orbital makes its removal easier than removal from the singly occupied 3p orbitals of P.')]
