transitionions=[('Fe',26,'2+',r'[Ar]3d^{6}',6),('Fe',26,'3+',r'[Ar]3d^{5}',5),('Cu',29,'2+',r'[Ar]3d^{9}',9),('Sc',21,'3+',r'[Ar]',0)]
