isomers=[('C4H10','acyclic alkanes',['butane','2-methylpropane']),('C3H8O','saturated acyclic alcohols and ethers',['propan-1-ol','propan-2-ol','methoxyethane']),('C4H8O','saturated acyclic aldehydes and ketones only',['butanal','2-methylpropanal','butan-2-one']),('C5H12','acyclic alkanes',['pentane','2-methylbutane','2,2-dimethylpropane'])]
