nmritems=[('C3H6O2',[(8.1,1,'singlet'),(4.2,2,'quartet'),(1.3,3,'triplet')],'ethyl methanoate','HCOOCH2CH3',['8.1 ppm: formyl proton adjacent to the ester carbonyl.','4.2 ppm: O–CH2 group, split by three neighbouring methyl protons.','1.3 ppm: CH3 group, split by two neighbouring methylene protons.'],['H','C','O','CH₂','CH₃'],(1,)),('C4H8O2',[(3.7,3,'singlet'),(2.3,2,'quartet'),(1.1,3,'triplet')],'methyl propanoate','CH3CH2COOCH3',['3.7 ppm: O–CH3 group, with no adjacent proton-bearing carbon across the oxygen.','2.3 ppm: CH2 next to the carbonyl, split by three neighbouring methyl protons.','1.1 ppm: terminal CH3, split by two neighbouring methylene protons.'],['CH₃','CH₂','C','O','CH₃'],(2,)),('C4H8O2',[(4.1,2,'quartet'),(2.0,3,'singlet'),(1.2,3,'triplet')],'ethyl ethanoate','CH3COOCH2CH3',['4.1 ppm: O–CH2, split by three neighbouring methyl protons.','2.0 ppm: CH3 attached to a carbonyl carbon that bears no hydrogen.','1.2 ppm: terminal ethyl CH3, split by two neighbouring methylene protons.'],['CH₃','C','O','CH₂','CH₃'],(1,)),('C4H8O',[(2.4,2,'quartet'),(2.1,3,'singlet'),(1.0,3,'triplet')],'butan-2-one','CH3COCH2CH3',['2.4 ppm: CH2 next to a carbonyl, split by three neighbouring methyl protons.','2.1 ppm: CH3 directly attached to the carbonyl, with no neighbouring proton on the carbonyl carbon.','1.0 ppm: terminal CH3, split by two neighbouring methylene protons.'],['CH₃','C','CH₂','CH₃'],(1,))]
for v,(formula,signals,name,condensed,assignments,labels,carbonyls) in enumerate(nmritems,1):
    ir='an ester carbonyl and a C–O band' if v<4 else 'a ketone carbonyl but no O–H or C–O band'
    b.add('S32-combined-nmr','S3.2',v,'Combining formula, infrared and proton NMR',f'Constructed analytical data identify molecular formula {c(formula)}. Infrared data show {ir}. The proton NMR data are listed below. Use first-order splitting; ignore long-range coupling and any weak isotope satellites.'+table(['Chemical shift / ppm','Integral','Multiplicity'],[(f'{ppm:.1f}',integral,multi) for ppm,integral,multi in signals]),level='ahl',kind='data-based',diagram=nmr_svg(signals),parts=[P('Deduce a structure and give its IUPAC name.',A(c(condensed)+'.'),A(name+'.')),P('Assign each NMR signal to a proton environment and explain the splitting where it occurs.',*[A(x) for x in assignments]),P('Check the proposed structure against the total integration and the infrared evidence.',Rn(f'The total integral is {sum(x[1] for x in signals)}, matching the number of hydrogens in the formula, and the proposed structure contains the functional groups indicated by the infrared data.'))],worked=chain_svg(labels,carbonyls=carbonyls))

b.extend(5,P('Write the gaseous process defining the first electron affinity of chlorine, and explain why energy is released in this case.',A(m(r'\mathrm{Cl(g)}+e^{-}\rightarrow\mathrm{Cl^{-}(g)}')+'.'),Rn('The incoming electron is attracted to the nucleus and the resulting gaseous chloride ion is lower in energy than the separated atom and electron.')))
b.extend(13,P('State the oxidation state of hydrogen in '+c('NaH')+' and of oxygen in '+c('H2O2')+'.',A('Hydrogen in sodium hydride: −1.'),A('Oxygen in hydrogen peroxide: −1.')))
b.extend(16,P('Sulfur oxides from fuel combustion enter the atmosphere. Explain how they can contribute to acid deposition and give one environmental consequence.',Rn('Sulfur oxides form acids when they react with atmospheric water and oxygen, lowering the pH of precipitation or deposited moisture.'),A('Accept acidification of lakes or soils, damage to organisms, or reaction with carbonate stone that erodes buildings.')))
b.extend(41,P('Classify '+c('CH3NH2')+', '+c('(CH3)2NH')+' and '+c('(CH3)3N')+' as primary, secondary or tertiary amines. State the classification rule.',A(c('CH3NH2')+': primary.'),A(c('(CH3)2NH')+': secondary.'),A(c('(CH3)3N')+': tertiary.'),Rn('Count the carbon-containing groups directly attached to nitrogen: one, two or three, respectively.')))
b.extend(42,P('Classify propan-1-ol, butan-2-ol and 2-methylpropan-2-ol as primary, secondary or tertiary alcohols, and state the rule.',A('Propan-1-ol: primary.'),A('Butan-2-ol: secondary.'),A('2-methylpropan-2-ol: tertiary.'),Rn('Count the carbon atoms directly bonded to the carbon bearing the hydroxy group: one, two or three.')))
b.extend(44,P('Classify each chlorine-bearing carbon in the displayed compound as primary, secondary or tertiary, and justify your choice.',A('Both are primary.'),Rn('Each chlorine-bearing carbon is bonded directly to only one other carbon atom.')))
for number,n,halogen in [(61,2,'Cl'),(62,2,'Br'),(63,3,'Cl'),(64,3,'Br')]:
    b.extend(number,P('Suppose the molecular ion fragments by breaking the carbon-halogen bond, with the positive charge retained on the hydrocarbon fragment. Give the fragment-ion formula and its m/z value.',A(c(f'C{n}H{2*n+1}','+')+'.'),A(f'For a singly charged ion, m/z = 12 × {n} + {2*n+1} = {14*n+1}.')))
b.save(72,{'S3.1':36,'S3.2':36})
